-- Rollback-only fixtures. No accounts, staff or business records are retained.
begin;
do $test$
declare u uuid:=gen_random_uuid();dev uuid:=gen_random_uuid();shop uuid;a uuid:=gen_random_uuid();settings jsonb;candidate jsonb;result jsonb;ver integer;failed boolean;before_options jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data,created_at)values(u,'account-settings-test@example.invalid',now(),'{}',now()),(dev,'staff-developer-account-settings@staff.printshopledger.invalid',now(),'{}',now());
 shop:=(public.complete_business_registration(u,dev,'Account settings test','Tester',repeat('b',64),'https://print-shop-ledger.vercel.app/#developer_activation='||repeat('b',64))->>'shopId')::uuid;
 perform set_config('request.jwt.claim.sub',u::text,true);
 update public.shop_members set access_level=4,rank=4,role='developer'where shop_id=shop and user_id=u;
 select b.settings,b.version into settings,ver from public.business_settings b where shop_id=shop;
 if settings is null then settings:='{"businessName":"Account settings test","address":"","phones":"","email":"","website":"","socials":"","logo":"","logoVariants":{"complete":{"light":"","dark":""},"stacked":{"light":"","dark":""},"horizontal":{"light":"","dark":""},"wordmark":{"light":"","dark":""},"icon":{"light":"","dark":""}},"logoUsage":{"sidebar":"horizontal","documents":"complete","favicon":"icon"},"primary":"#124b40","accent":"#d9a126","theme":"system","backgrounds":{"light":{"canvas":"","surface":"","surfaceAlt":""},"dark":{"canvas":"","surface":"","surfaceAlt":""}},"options":{"paymentMethods":[{"label":"Cash","kind":"Cash","enabled":true},{"label":"POS","kind":"POS","enabled":true},{"label":"Transfer","kind":"Transfer","enabled":true}],"expenseCategories":["Materials","Electricity","Fuel","Rent","Wages","Maintenance","Delivery","Outsourcing","Internet / phone","Other"],"jobSources":["In shop / USB","Shop network","WhatsApp","Email","Other"],"stockReasons":["Restocking","Stock Count Correction","Returned Stock","Damaged Stock"],"materialUnits":["sheet","piece","metre","square metre","roll","kilogram","litre"],"jobStages":["Added","In Queue","Printing","Completed","Collected"]},"corrections":{"recentDays":7},"security":{"autoLockMinutes":0,"syncMinutes":2},"jobs":{"defaultDuration":{"value":0,"unit":"days"},"paymentPrefill":"suggested","descriptionMode":"required","stockBelowZero":"allow"},"pricing":{"enabled":false,"maxTemplates":100,"auditRanks":[2,3],"templates":[]},"periods":{"dashboard":"month","reports":"month","pointOfService":"30days","jobs":"all","payments":"all","expenses":"all","stockHistory":"all","mySales":"today"},"discounts":{"maxPercent":{"1":0,"2":20,"3":100}},"terms":{"preset":"print","job":"job","jobs":"jobs","service":"service","services":"services","material":"material","materials":"materials","stages":{"Added":"Added","Completed":"Completed","Collected":"Collected"}},"pageAccess":{"1":["Point of Service","Quotations","Pricing Templates","My Sales","Print Settings","My Account"],"2":["Dashboard","Reports","Point of Service","Quotations","Pricing Templates","My Sales","Jobs","Customers","Payment Reminders","Payments","Expenses","Payees","Accounts","Materials","Services","Edit Products","Stock History","Print Settings","Users","My Account","Conflict Inbox","Sale Adjustments","Material Waste"],"3":["Dashboard","Reports","Point of Service","Quotations","Pricing Templates","My Sales","Jobs","Customers","Payment Reminders","Payments","Expenses","Payees","Accounts","Materials","Services","Edit Products","Stock History","Print Settings","Users","My Account","Conflict Inbox","Sale Adjustments","Material Waste"]},"pageAccessVersion":3,"settingsTabs":{"2":["Profile & logo","Appearance","Receipts","Payment methods","Dropdowns & workflow","Jobs & payments","Pricing templates","Corrections","Security","Branches"],"3":["Profile & logo","Appearance","Receipts","Payment methods","Dropdowns & workflow","Jobs & payments","Pricing templates","Corrections","Security","Branches"]},"settingsTabsVersion":1,"receipt":{"showLogo":true,"showBusinessName":true,"showAddress":true,"showContacts":true,"footer":"Thank you for your business.","logoLayout":"","logoPosition":"right","headline":"description","showSubline":true,"showJobId":true,"showQuantity":true,"showSize":true,"showSource":true,"showDueDate":true,"showPaidBefore":true,"showPaidNow":true,"showItemBalance":true,"showCustomerPhone":true,"showCashier":true,"showPaymentDate":true,"showPaymentMethod":true,"showWalletMovements":true,"showAccountBalances":true,"showNote":true},"receiptPage":{"logoLayout":"","logoPosition":"right","showLogo":true,"showBusinessName":true,"showAddress":true,"showContacts":true,"footer":"Thank you for your business.","headline":"description","showSubline":true,"showJobId":true,"showQuantity":true,"showSize":true,"showSource":true,"showDueDate":true,"showPaidBefore":true,"showPaidNow":true,"showItemBalance":true,"showCustomerPhone":true,"showCashier":true,"showPaymentDate":true,"showPaymentMethod":true,"showWalletMovements":true,"showAccountBalances":true,"showNote":true},"documents":{"watermark":false,"watermarkLogoLayout":"","invoiceTerms":"","quotationTerms":"","showTermsOnRoll":false},"poweredBy":{"text":"","receipts":false,"pages":false,"reports":false,"shares":false},"branches":[],"branchAccess":{}}'::jsonb;ver:=0;end if;
 settings:=settings||jsonb_build_object('settingsTabsVersion',1,'pageAccessVersion',3,'settingsTabs',jsonb_build_object('2',jsonb_build_array('Payment methods'),'3',jsonb_build_array('Dropdowns & workflow')));
 settings:=jsonb_set(settings,'{pageAccess,2}',(settings->'pageAccess'->'2')||jsonb_build_array('Business Settings'));
 settings:=jsonb_set(settings,'{pageAccess,3}',(settings->'pageAccess'->'3')||jsonb_build_array('Business Settings'));
 -- Avoid duplicate Business Settings entries if the registration default ever changes.
 settings:=jsonb_set(settings,'{pageAccess,2}',(select jsonb_agg(distinct x)from jsonb_array_elements(settings->'pageAccess'->'2')x));
 settings:=jsonb_set(settings,'{pageAccess,3}',(select jsonb_agg(distinct x)from jsonb_array_elements(settings->'pageAccess'->'3')x));
 result:=public.save_business_settings(shop,ver,settings);settings:=result->'settings';ver:=(result->>'version')::int;
 perform public.apply_operations_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','account.created','data',jsonb_build_object('id',a,'name','Bank','accountType','bank','openingDate','2026-10-01','openingBalance',10000,'methods',jsonb_build_array('Transfer'),'modifiedBy',u)));
 perform public.apply_operations_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','account.updated','data',jsonb_build_object('id',a,'baseVersion',1,'name','POS account','accountType','pos','openingDate','2026-10-02','openingBalance',-5000,'methods',jsonb_build_array('POS'),'modifiedBy',u)));
 if not exists(select 1 from public.business_operations_records where shop_id=shop and id=a and data->>'name'='POS account'and data->>'openingDate'='2026-10-02'and data->>'openingBalance'='-5000')then raise exception 'Account creation fields were not editable';end if;
 before_options:=settings->'options';
 update public.shop_members set access_level=2,rank=2,role='admin'where shop_id=shop and user_id=u;
 candidate:=jsonb_set(settings,'{options,paymentMethods}',(settings->'options'->'paymentMethods')||jsonb_build_array(jsonb_build_object('label','QA Bank','kind','Transfer','enabled',true)));
 candidate:=jsonb_set(candidate,'{options,expenseCategories}',jsonb_build_array('Should not save'));
 result:=public.save_business_settings(shop,ver,candidate);settings:=result->'settings';ver:=(result->>'version')::int;
 if settings->'options'->'expenseCategories' is distinct from before_options->'expenseCategories' or not exists(select 1 from jsonb_array_elements(settings->'options'->'paymentMethods')x where x->>'label'='QA Bank')then raise exception 'Payment-method section isolation failed';end if;
 failed:=false;begin perform public.apply_operations_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','account.updated','data',jsonb_build_object('id',a,'baseVersion',2,'name','Forbidden','accountType','bank','methods','[]'::jsonb,'modifiedBy',u)));exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Admin changed account setup';end if;
 before_options:=settings->'options';
 update public.shop_members set access_level=3,rank=3,role='manager'where shop_id=shop and user_id=u;
 candidate:=jsonb_set(settings,'{options,expenseCategories}',jsonb_build_array('Updated category'));
 candidate:=jsonb_set(candidate,'{options,paymentMethods}',jsonb_build_array(jsonb_build_object('label','Forbidden','kind','Cash','enabled',true)));
 result:=public.save_business_settings(shop,ver,candidate);
 if result->'settings'->'options'->'paymentMethods' is distinct from before_options->'paymentMethods' or result->'settings'->'options'->'expenseCategories' is distinct from jsonb_build_array('Updated category')then raise exception 'Dropdown section isolation failed';end if;
end $test$;
rollback;
